import React from 'react';
import Animated, { useAnimatedStyle } from 'react-native-reanimated';

import { styles } from '../../../styles';
import { enableAndroidHardwareTextures, getStyle, getWebDependencies } from '../../../utils';

import type { BuiltinThumbsProps } from '../../../types';

export default function Circle({
  width,
  height,
  borderRadius,
  adaptiveColor,
  thumbAnimatedStyle,
  innerStyle,
  solidColor,
  style,
}: BuiltinThumbsProps) {
  const computedStyle = { width, height };
  const circleStyle = {
    borderRadius,
    borderWidth: 1,
    width: '100%',
    height: '100%',
  } as const;
  const borderColor = getStyle(innerStyle, 'borderColor');

  const adaptiveColorStyle = useAnimatedStyle(
    () => ({ borderColor: borderColor ?? adaptiveColor.value }),
    getWebDependencies([borderColor, adaptiveColor]),
  );

  return (
    <Animated.View
      style={[styles.handle, style, computedStyle, thumbAnimatedStyle]}
      renderToHardwareTextureAndroid={enableAndroidHardwareTextures}
    >
      <Animated.View style={[circleStyle, styles.shadow, adaptiveColorStyle, solidColor, innerStyle]} />
    </Animated.View>
  );
}
